-- Gabarits commerciaux PSP-02, PSP-03, PSP-04 (séquence de prospection) et FOU-05 (recrutement des fournisseurs) : exemples de la
-- maquette remplacés par les variables que passent leurs expéditeurs (comms.planifier_prospection, maint.approuver/planifier_invitations).
-- Les chiffres inventés de la maquette sont retirés (99,6 % des loyers perçus, 18 jours, 42 logements à Lévis, étude de cas Limoilou) :
-- un courriel commercial ne peut pas affirmer ce que Lease Lane ne peut pas prouver. Seules des variables toujours remplies sont utilisées
-- (quartier, territoire, service et gestionnaire peuvent être vides).
-- L'adresse du bureau (LCAP) est maintenant dans _shared/gabarits.ts. Les quatre gabarits RESTENT INACTIFS : les activer enverrait de vrais
-- courriels (séquence en cours, fournisseurs approuvés). Activation dans Studio › Gabarits, une fois le texte approuvé par le client.
update comms.email_templates set subject = 'Gestion immobilière pour {entreprise}', preheader = 'Une gestion locale à Québec et à Lévis, sans engagement.',
  variables = array['entreprise', 'gestionnaire'], contenu = $j${"subject": "Gestion immobilière pour {entreprise}", "pre": "Une gestion locale à Québec et à Lévis, sans engagement.", "label": "Gestion immobilière", "icon": "building", "eyebrow": "Gestion immobilière", "title": "Une gestion locale pour vos immeubles", "intro": "Bonjour, Lease Lane gère des immeubles locatifs à Québec et à Lévis. Nous aimerions vous présenter notre façon de faire, en 15 minutes.", "blocks": [["bullets", {"items": ["Location des logements et sélection des locataires", "Perception des loyers et relances", "Urgences prises en charge 24 h sur 24"]}]], "cta": {"l": "Planifier un appel de 15 minutes", "href": "mailto:info@leaselane.ca?subject=Appel%20de%2015%20minutes", "link": "Pas intéressé? Se désabonner en un clic."}, "sign": {"name": "{gestionnaire}", "role": "Location et prospection · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel parce que vos coordonnées d’entreprise sont publiques. Un clic suffit pour ne plus rien recevoir.", "commercial": true}, "spec": {"trigger": "Ajout à la séquence, après révision humaine", "send": "Automatique, liste approuvée", "when": "Jour ouvrable, entre 9 h et 17 h ; jamais entre 22 h et 8 h", "lcap": "Commercial · consentement vérifié · désabonnement obligatoire", "note": "Arrêt dès qu’il y a une réponse ; 5 tentatives au plus."}, "exemple": {"entreprise": "Gestion Bélanger", "gestionnaire": "Laurence P."}}$j$::jsonb
where code = 'PSP-02';

update comms.email_templates set subject = 'Re : gestion immobilière pour {entreprise}', preheader = 'Une question de 2 minutes : qui gère vos immeubles aujourd’hui?',
  variables = array['entreprise', 'gestionnaire'], contenu = $j${"subject": "Re : gestion immobilière pour {entreprise}", "pre": "Une question de 2 minutes : qui gère vos immeubles aujourd’hui?", "label": "Gestion immobilière", "icon": "message", "eyebrow": "Suivi", "title": "Une question rapide", "intro": "Bonjour, je reviens vers vous : gérez-vous vos immeubles vous-même, ou avec un gestionnaire? Selon votre réponse, je vous enverrai une estimation adaptée, ou je ne vous écrirai plus.", "blocks": [], "cta": {"l": "Répondre en un clic", "href": "mailto:info@leaselane.ca?subject=Gestion%20de%20mes%20immeubles", "link": "Ne plus recevoir nos messages"}, "sign": {"name": "{gestionnaire}", "role": "Location et prospection · Lease Lane"}, "foot": {"reason": "Vous recevez ce courriel à la suite de notre message de la semaine dernière.", "commercial": true}, "spec": {"trigger": "Jour 7, seulement sans réponse", "send": "Automatique", "when": "Jour ouvrable, entre 9 h et 17 h", "lcap": "Commercial · désabonnement obligatoire"}, "exemple": {"entreprise": "Gestion Bélanger", "gestionnaire": "Laurence P."}}$j$::jsonb
where code = 'PSP-03';

update comms.email_templates set variables = array['gestionnaire'], contenu = $j${"subject": "Je ne vous écrirai plus après ce message", "pre": "Notre offre reste valable si vous changez d’idée.", "label": "Gestion immobilière", "icon": "flag", "eyebrow": "Dernier message", "title": "Merci de votre temps", "intro": "Bonjour, je ne vous relancerai plus. Si un jour vous cherchez un gestionnaire pour vos immeubles, il suffira de répondre à ce courriel.", "blocks": [], "cta": {"l": "Visiter leaselane.ca", "href": "https://leaselane.ca"}, "sign": {"name": "{gestionnaire}", "role": "Location et prospection · Lease Lane"}, "foot": {"reason": "Vous recevez ce dernier courriel à la suite de nos messages précédents.", "commercial": true}, "spec": {"trigger": "Jour 14, seulement sans réponse", "send": "Automatique", "when": "Jour ouvrable", "lcap": "Commercial · désabonnement obligatoire", "note": "Le contact sort de la séquence après ce message."}, "exemple": {"gestionnaire": "Laurence P."}}$j$::jsonb
where code = 'PSP-04';

-- La relance (maint.planifier_invitations) ne passe pas de gestionnaire : signature d'équipe.
update comms.email_templates set preheader = 'Documents à fournir : {documents}', variables = array['entreprise', 'documents'],
  contenu = $j${"subject": "Rejoignez la banque de fournisseurs de Lease Lane", "pre": "Documents à fournir : {documents}", "label": "Recrutement", "icon": "users", "eyebrow": "Recrutement", "title": "Travaillons ensemble", "intro": "Bonjour, Lease Lane gère des immeubles locatifs à Québec et à Lévis. Nous cherchons des entreprises fiables comme {entreprise} pour l’entretien et les réparations de nos immeubles.", "blocks": [["kv", {"rows": [["Documents à fournir", "{documents}"], ["Vos prix", "Pour les services que vous offrez"]]}]], "cta": {"l": "Répondre à l’invitation", "href": "mailto:info@leaselane.ca?subject=Banque%20de%20fournisseurs"}, "sign": {"ini": "LL", "name": "L’équipe Lease Lane", "role": "Recrutement des fournisseurs"}, "foot": {"reason": "Vous recevez ce courriel parce que votre entreprise affiche publiquement ses services.", "commercial": true}, "spec": {"trigger": "Fournisseur trouvé par l’agent, puis vérifié", "send": "Après approbation humaine", "when": "Jour ouvrable, entre 9 h et 17 h", "lcap": "Commercial · désabonnement obligatoire", "note": "Une invitation, une relance au plus."}, "exemple": {"entreprise": "Déneigement Rive-Sud", "documents": "Licence RBQ, preuve d’assurance, NEQ"}}$j$::jsonb
where code = 'FOU-05';
